// Standard Sindhi Braille — browser translator.
// A direct port of tools/sindhi_braille.py; the tables are generated from it,
// so the two cannot drift apart.  Verified against the same 74 worked examples
// printed in the Sindhi Language Authority's standard guide.

const SHADDA = 'ّ';

function cellToAscii(dots) {
  let v = 0;
  for (const d of dots) v |= 1 << (parseInt(d, 10) - 1);
  return T.BA[v];
}
function cellToUnicode(dots) {
  let v = 0;
  for (const d of dots) v |= 1 << (parseInt(d, 10) - 1);
  return String.fromCharCode(0x2800 + v);
}

function digits(tok, i, out) {
  out.push(T.NUMSIGN);
  while (i < tok.length) {
    const d = T.ARABIC_DIGIT[tok[i]] || tok[i];
    if (d >= '0' && d <= '9') { out.push(T.DIGIT[d]); i++; continue; }
    const nraw = tok[i + 1] || '';
    const n = T.ARABIC_DIGIT[nraw] || nraw;
    const nIsDigit = n >= '0' && n <= '9' && n !== '';
    if (tok[i] === '.' && nIsDigit) { out.push(T.DECPT); i++; continue; }
    if (tok[i] === ',' && nIsDigit) { out.push(T.NUMCOMMA); i++; continue; }
    break;
  }
  return i;
}

function isDigits(s) { return s.length > 0 && /^[0-9]+$/.test(s); }

function fraction(tok) {
  const k = tok.indexOf('/');
  if (k < 0) return null;
  const conv = s => [...s].map(c => T.ARABIC_DIGIT[c] || c).join('');
  const a = conv(tok.slice(0, k)), b = conv(tok.slice(k + 1));
  if (!isDigits(a) || !isDigits(b)) return null;
  const out = [T.NUMSIGN];
  if (a !== '1') for (const d of a) out.push(T.DIGIT[d]);
  for (const d of b) out.push(T.LOWDIGIT[d]);
  return out;
}

function roman(tok) {
  const t = tok.replace(/\.$/, '');
  if (!t) return null;
  for (const c of t) if (!(c in T.ROMAN)) return null;
  const out = [T.LETTERSIGN];
  for (const c of t) out.push(T.ROMAN[c]);
  if (tok.endsWith('.')) out.push(T.PUNCT['.']);
  return out;
}

/* Words whose marks are obligatory, written whether or not anyone typed them.
   Order from Riaz Hussain Memon, 15 August 2026: the shadda falls between the two
   lams, which agrees with the Arabic braille convention of writing the shadda
   before the letter it doubles.  The khari zabar sits after the lam and before
   the ه, as Urdu braille writes the whole ligature. */
const ALLAH_CELLS = ['1','123','6','123','4','125'];
const ALWAYS_MARKED = (() => {
  /* Every way the name is actually typed, all giving the same six cells: bare,
     with the shadda, with the shadda and the khari zabar, or as the single
     ligature; and ending in ه, the Urdu ہ, or ھ from a keyboard that emits
     do-chashmi.  The marks are obligatory in braille whether or not they were
     typed.  Before this the bare spelling gave six cells and the properly
     marked one gave four, because the marks were stripped on the way through:
     the spelling most likely to be right was the one that came out wrong. */
  const out = {};
  for (const heh of ['\u0647', '\u06c1', '\u06be'])
    for (const shadda of ['', '\u0651'])
      for (const khari of ['', '\u0670'])
        out['\u0627\u0644\u0644' + shadda + khari + heh] = ALLAH_CELLS.slice();
  out['\ufdf2'] = ALLAH_CELLS.slice();
  return out;
})();

/* The Arabic presentation ligatures U+FDF0..U+FDFD.  Two have a sign of their
   own - ﷲ above and ﷺ in ABBREV - and those win.  The rest were dropped in
   silence: ﷻ and ﷽ went in and nothing came out.  Unicode already says what
   each stands for, so they expand to that text and translate as ordinary
   words.  Nothing here is invented. */
const LIGATURE = (() => {
  const out = {};
  for (let cp = 0xFDF0; cp <= 0xFDFD; cp++) {
    const ch = String.fromCharCode(cp);
    if (ch in ALWAYS_MARKED || cp === 0xFDFA) continue;
    const ex = ch.normalize('NFKC');
    if (ex !== ch) out[ch] = ex;
  }
  out['\ufdfd'] = 'بسم الله الرحمٰن الرحيم';   // ﷽ has no decomposition
  return out;
})();

function wordToCells(w, diacritics, arithmetic, grade2) {
  if (w in ALWAYS_MARKED) return ALWAYS_MARKED[w].slice();
  if (w.length > 1 && (w.slice(-1) in T.PUNCT) && (w.slice(0, -1) in ALWAYS_MARKED))
    return ALWAYS_MARKED[w.slice(0, -1)].concat([T.PUNCT[w.slice(-1)]]);
  w = [...w].map(c => T.SPELLOUT[c] || c).join('');
  w = [...w].map(c => T.NORMALISE[c] || c).join('');

  if (w.includes('/')) { const f = fraction(w); if (f) return f; }
  if (w in T.MATH) return T.MATH[w].slice();
  if (w.endsWith('%') && w.length > 1) {                 // 50% -> 25 1234 3456 5 0
    const body = [...w.slice(0, -1)].map(c => T.ARABIC_DIGIT[c] || c).join('');
    if (/^[0-9]+$/.test(body)) {
      const out = T.MATH['%'].slice(); digits(body, 0, out); return out;
    }
  }
  const r = roman(w); if (r) return r;
  if (w.length === 2 && (w[0] in T.LETTER) && (w[1] === '.' || w[1] === '۔'))
    return [T.LETTERSIGN, ...T.LETTER[w[0]], T.PUNCT['.']];
  if (w.length && [...w].every(c => (c.toLowerCase() in T.LATIN) || (c in T.PUNCT))) {
    const out = T.FOREIGN_OPEN.slice();
    for (const c of w) {
      if (c in T.PUNCT) { out.push(T.PUNCT[c]); continue; }
      if (c >= 'A' && c <= 'Z') out.push(T.LATINCAP);
      out.push(T.LATIN[c.toLowerCase()]);
    }
    return out.concat(T.FOREIGN_CLOSE);
  }

  const out = []; let i = 0;
  while (i < w.length) {
    if (grade2 && i > 0) {                 // ڳانڊڙا: never word-initial
      let hit = null;
      for (const [g, cells] of G2.groups)
        if (w.startsWith(g, i)) { hit = [g, cells]; break; }
      if (hit) { out.push(...hit[1]); i += hit[0].length; continue; }
    }
    const two = w.slice(i, i + 2);
    if (two in T.DIGRAPH) { out.push(...T.DIGRAPH[two]); i += 2; continue; }
    let c = w[i];
    if (c in T.ARABIC_DIGIT) c = T.ARABIC_DIGIT[c];
    if (c >= '0' && c <= '9') {
      i = digits(w, i, out);
      if (i < w.length && w[i] === ':') { out.push(T.RATIO); i++; continue; }
      if (i < w.length && (w[i] in T.PUNCT)) out.push(T.NUMEND);
      continue;
    }
    if (c in T.LETTER) {
      if (diacritics && w[i + 1] === SHADDA) out.push(T.DIACRITIC[SHADDA]);
      out.push(...T.LETTER[c]); i++; continue;
    }
    if (c in T.DIACRITIC) {
      if (diacritics && c !== SHADDA) out.push(T.DIACRITIC[c]);
      i++; continue;
    }
    if (c in T.QUOTE) { out.push(...T.QUOTE[c]); i++; continue; }
    if (arithmetic && (c === '{' || c === '}')) {
      out.push(...T.MATHBRACKET[c]); i++; continue;
    }
    if (c in T.BRACKET) {
      out.push(...(arithmetic ? T.MATHBRACKET : T.BRACKET)[c]); i++; continue;
    }
    if (c in T.PUNCT) { out.push(T.PUNCT[c]); i++; continue; }
    i++;
  }
  return out;
}

function abbreviate(words) {
  const strip = s => s.replace(/[.۔،]+$/g, '').replace(/^[.۔،]+/g, '');
  const out = []; let i = 0;
  while (i < words.length) {
    let hit = null;
    for (const [phrase, cells] of T.ABBREV) {
      const parts = phrase.split(' ');
      const seg = words.slice(i, i + parts.length).map(strip);
      if (seg.length === parts.length && seg.every((x, k) => x === parts[k])) {
        hit = [parts.length, cells]; break;
      }
    }
    if (hit) { out.push(hit[1].slice()); i += hit[0]; }
    else { out.push(words[i]); i++; }
  }
  return out;
}

/* A comparison sign takes a space before it and none after. The guide prints
   this six times out of six in its worked sums, and Riaz Hussain Memon said the
   same independently on 15 August 2026. Both engines wrote a space on both
   sides until August 2026; the check that should have caught it recorded the
   grouping from our own output rather than from the page. */
function closeComparison(toks) {
  const eq = T.MATH['='];
  const same = (a, b) => a.length === b.length && a.every((x, i) => x === b[i]);
  const out = [];
  for (let i = 0; i < toks.length; i++) {
    if (same(toks[i], eq) && i + 1 < toks.length) {
      out.push(toks[i].concat(toks[i + 1])); i++; continue;
    }
    out.push(toks[i]);
  }
  return out;
}

function mergeForeign(toks) {
  const fo = T.FOREIGN_OPEN, fc = T.FOREIGN_CLOSE;
  const isf = t => t.length > 4 &&
    t[0] === fo[0] && t[1] === fo[1] &&
    t[t.length - 2] === fc[0] && t[t.length - 1] === fc[1];
  const out = []; let k = 0;
  while (k < toks.length) {
    if (!isf(toks[k])) { out.push(toks[k]); k++; continue; }
    let j = k;
    while (j + 1 < toks.length && isf(toks[j + 1])) j++;
    const run = toks.slice(k, j + 1);
    run.forEach((t, m) => {
      const body = t.slice(2, t.length - 2);
      out.push([].concat(m === 0 ? fo : [], body, m === run.length - 1 ? fc : []));
    });
    k = j + 1;
  }
  return out;
}

/* a line carrying an arithmetic operator uses the arithmetic brackets (p.53) */
function isArithmetic(words) {
  return words.some(w => typeof w === 'string' && (w in T.MATH) && w !== '-' && w !== 'x');
}

function translate(text, opts) {
  opts = opts || {};
  const diacritics = !!opts.diacritics;
  const doubling = opts.doubling !== false;
  const waw = opts.waw !== false;
  const poetry = !!opts.poetry;
  const grade2 = !!opts.grade2;
  const G2STRIP = /^[.\u06d4\u060c\u061f!\u061b:]+|[.\u06d4\u060c\u061f!\u061b:]+$/g;
  const takhallus = opts.takhallus || null;
  const lines = [];
  let stanzaOpen = false;
  text = [...text].map(c => LIGATURE[c] || c).join('');
  for (const para of text.split('\n')) {
    const words = abbreviate(para.split(' ').filter(x => x.length));
    const arith = isArithmetic(words);
    let toks = []; let k = 0;
    while (k < words.length) {
      const w = words[k];
      if (Array.isArray(w)) { toks.push(w); k++; continue; }
      const bare = [...w].filter(ch => !(ch in T.PUNCT)).join('');
      let nxt = k + 1 < words.length ? words[k + 1] : null;
      let nxt2 = k + 2 < words.length ? words[k + 2] : null;
      if (Array.isArray(nxt)) nxt = null;
      if (Array.isArray(nxt2)) nxt2 = null;
      if (doubling && nxt !== null && bare && w === bare &&
          [...nxt].filter(ch => !(ch in T.PUNCT)).join('') === bare) {
        const cells = wordToCells(nxt, diacritics, arith, grade2);
        const base = wordToCells(bare, diacritics, arith, grade2);
        toks.push(base.concat(T.DOUBLING, cells.slice(base.length)));
        k += 2; continue;
      }
      if (waw && nxt2 !== null && nxt === 'و') {
        toks.push(wordToCells(w, diacritics, arith, grade2)
          .concat([T.WAW_ATF], wordToCells(nxt2, diacritics, arith, grade2)));
        k += 3; continue;
      }
      if (grade2) {
        let hit = null;
        for (const [parts, cells] of G2.phrases) {
          const seg = words.slice(k, k + parts.length);
          if (seg.length === parts.length && !seg.some(Array.isArray) &&
              seg.every((x, j) => x.replace(G2STRIP, '') === parts[j])) {
            hit = [parts.length, cells]; break;
          }
        }
        if (hit) { toks.push(hit[1].slice()); k += hit[0]; continue; }
        const bare2 = w.replace(G2STRIP, '');
        if (bare2 in G2.words) {
          const tail = [...w.slice(bare2.length)]
            .filter(c => c in T.PUNCT).map(c => T.PUNCT[c]);
          toks.push(G2.words[bare2].concat(tail)); k++; continue;
        }
      }
      toks.push(wordToCells(w, diacritics, arith, grade2)); k++;
    }
    if (takhallus && toks.length) {
      const mark = wordToCells(takhallus, diacritics, arith).join(',');
      for (let j = 0; j < toks.length; j++)
        if (toks[j].join(',') === mark) toks[j] = [T.TAKHALLUS].concat(toks[j]);
    }
    if (poetry && toks.length) {
      // the pair opens the stanza and stands on its own, with a space after it
      if (!stanzaOpen) { toks = [T.POETRY.slice()].concat(toks); stanzaOpen = true; }
      toks[toks.length - 1] = toks[toks.length - 1].concat([T.POETRY[0]]);
    } else if (poetry) stanzaOpen = false;

    if (arith) toks = closeComparison(toks);
    lines.push(mergeForeign(toks));
  }
  if (poetry)                                   // a full stop closes the stanza
    lines.forEach((ln, j) => {
      const nxt = j + 1 < lines.length ? lines[j + 1] : null;
      if (ln.length && (nxt === null || !nxt.length))
        ln[ln.length - 1] = ln[ln.length - 1].concat([T.PUNCT['.']]);
    });
  return lines;
}

function toUnicode(lines) {
  return lines.map(toks =>
    toks.map(cs => cs.map(cellToUnicode).join('')).join('⠀')).join('\n');
}
function toDots(lines) {
  return lines.map(toks =>
    toks.map(cs => cs.join('-')).join('   ')).join('\n');
}
/* A direct port of to_brf() in tools/sindhi_braille.py.

   The width matters more than it looks.  An embosser breaks any line longer than
   the paper allows, and it breaks it wherever the line happens to run out - in
   the middle of a word.  A4 fits 28 cells.  Writing the file at 40 and embossing
   it on A4 is what splits words across lines. */
const BRF_HYPHEN = '36';
function toBrf(lines, width, height) {
  width  = width  || 28;
  height = height || 25;
  const pages = [];
  let cur = [];
  for (const toks of lines) {
    let row = '';
    for (const cs of toks) {
      let piece = cs.map(cellToAscii).join('');
      while (piece.length > width) {          // a single word wider than the page
        const cut = width - row.length - (row ? 1 : 0) - 1;
        if (cut > 2) {
          row = (row ? row + ' ' : '') + piece.slice(0, cut) + cellToAscii(BRF_HYPHEN);
          cur.push(row); row = ''; piece = piece.slice(cut);
        } else {
          if (row) { cur.push(row); row = ''; }
          cur.push(piece.slice(0, width - 1) + cellToAscii(BRF_HYPHEN));
          piece = piece.slice(width - 1);
        }
      }
      if (!row) row = piece;
      else if (row.length + 1 + piece.length <= width) row += ' ' + piece;
      else { cur.push(row); row = piece; }
    }
    cur.push(row);
    while (cur.length >= height) { pages.push(cur.slice(0, height)); cur = cur.slice(height); }
  }
  if (cur.length) pages.push(cur);
  return pages.map(p => p.join('\r\n')).join('\f') + '\r\n\f';
}

/* Back-translation: braille cells -> Sindhi.
   A direct port of back() in tools/sindhi_braille.py, including the word list
   that resolves the cells carrying more than one meaning. */

const CELL2LET = {};
for (const [L, cs] of Object.entries(T.LETTER))
  if (cs.length === 1 && !(cs[0] in CELL2LET)) CELL2LET[cs[0]] = L;
CELL2LET['236'] = 'ھ';

const DIG2    = Object.fromEntries(Object.entries(T.DIGIT).map(([k, v]) => [v, k]));
const LOW2DIG = Object.fromEntries(Object.entries(T.LOWDIGIT).map(([k, v]) => [v, k]));
const ROM2    = {};
for (const [k, v] of Object.entries(T.ROMAN)) if (!(v in ROM2)) ROM2[v] = k;
const LAT2    = {};
for (const [k, v] of Object.entries(T.LATIN)) if (!(v in LAT2)) LAT2[v] = k;
const ASPIRATE = { 'ج': 'جھ', 'گ': 'گھ', 'ڪ': 'ک' };
const MB_OPEN  = { [T.MATHBRACKET['('][0]]: '(', [T.MATHBRACKET['{'][0]]: '{' };
const MB_CLOSE = { [T.MATHBRACKET[')'][0]]: ')', [T.MATHBRACKET['}'][0]]: '}',
                   [T.MATHBRACKET[']'][0]]: ']' };
const MARK = { '256': '.', '236': '؟', '235': '!', '2': '،', '23': '؛', '25': ':' };

const MATH2 = {};
for (const [k, v] of Object.entries(T.MATH))
  if ('+−×÷=%'.includes(k)) MATH2[v.join(',')] = k;

const ABB2 = {};
for (const [ph, cs] of T.ABBREV) { const k = cs.join(','); if (!(k in ABB2)) ABB2[k] = ph; }

/* ۾ and ۽ are written out in full - مين and اَئين - so read back letter by letter
   they came out spelled rather than as the sign, ۽ as اءين.  That stray ا is what
   Riaz Hussain Memon spotted in a bait on 15 August 2026.  Reversing it on the
   whole token is exact: every cell has to match. */
const SIGN2 = {};
for (const sg of Object.keys(T.SPELLOUT)) {
  const k = wordToCells(T.SPELLOUT[sg], false, false, false).join(',');
  if (!(k in SIGN2)) SIGN2[k] = sg;
}


const WORDS = new Set(WORDLIST.split('\n').filter(Boolean));

const TAILMARK = new Set(Object.values(T.PUNCT));
const PUNCT_BACK = {};
for (const [k, v] of Object.entries(T.PUNCT)) if (!(v in PUNCT_BACK)) PUNCT_BACK[v] = k;

/* A contracted token -> the Sindhi it stands for, or null.  Whole token first,
   because a contraction stands for a whole word; then the ڳانڊڙا groups, which
   are written inside a word and never at its start. */
function degrade2(cells) {
  const body = cells.slice(); let tail = '';
  while (body.length && TAILMARK.has(body[body.length - 1])
         && !(body.join(',') in G2BACK)) {
    tail = (PUNCT_BACK[body.pop()] || '') + tail;
  }
  const hit = G2BACK[body.join(',')];
  if (hit !== undefined) return hit + tail;
  let out = '', i = 0, used = false;
  while (i < body.length) {
    const g = i > 0 ? G2GBACK[body.slice(i, i + 2).join(',')] : undefined;
    if (g !== undefined) { out += g; i += 2; used = true; continue; }
    const letter = CELL2LET[body[i]];
    if (letter === undefined) return null;
    out += letter; i++;
  }
  return used ? out + tail : null;
}

function back(lines, poetry, grade2) {
  const fo = T.FOREIGN_OPEN.join(','), fc = T.FOREIGN_CLOSE.join(',');
  const out = [];
  let foreign = false;       // a foreign run is closed by its own mark, so it
  for (let toks of lines) {  // survives the line break an embosser file puts in
    const words = [];
    toks = toks.map(t => t.slice());
    if (poetry && toks.length) {
      if (toks[0].join(',') === T.POETRY.join(',')) toks = toks.slice(1);
      else if (toks[0].slice(0, 2).join(',') === T.POETRY.join(','))
        toks[0] = toks[0].slice(2);
      const last = toks[toks.length - 1];
      if (last[last.length - 1] === T.PUNCT['.'] && last[last.length - 2] === T.POETRY[0])
        toks[toks.length - 1] = last.slice(0, -2).concat([T.PUNCT['.']]);
      else if (last[last.length - 1] === T.POETRY[0])
        toks[toks.length - 1] = last.slice(0, -1);
      for (let j = 0; j < toks.length; j++)
        if (toks[j][0] === T.TAKHALLUS && toks[j].length > 1) toks[j] = toks[j].slice(1);
    }
    for (let cells of toks) {
      // a run of Arabic, Urdu or English: opened by 56-236, closed by 356-23,
      // once around the whole run (guide p.46)
      if (cells.slice(0, 2).join(',') === fo && cells.length > 2) {
        foreign = true; cells = cells.slice(2);
      }
      const closing = cells.slice(-2).join(',') === fc;
      if (closing) cells = cells.slice(0, -2);
      if (foreign) {
        let t = '', j = 0;
        const P2 = {}; for (const [k, v] of Object.entries(T.PUNCT)) if (!(v in P2)) P2[v] = k;
        while (j < cells.length) {
          if (cells[j] === T.LATINCAP && cells[j + 1] && (cells[j + 1] in LAT2)) {
            t += LAT2[cells[j + 1]].toUpperCase(); j += 2; continue;
          }
          if (cells[j] in LAT2) { t += LAT2[cells[j]]; j++; continue; }
          if (cells[j] in P2)   { t += P2[cells[j]];   j++; continue; }
          j++;
        }
        words.push(t);
        if (closing) foreign = false;
        continue;
      }
      if (grade2) {
        const g2 = degrade2(cells);
        if (g2 !== null) { words.push(g2); continue; }
      }
      let s = '', i = 0;
      while (i < cells.length) {
        const c = cells[i];

        if (i === 0 && (c in MB_OPEN) && cells[i + 1] === T.NUMSIGN) {
          s += MB_OPEN[c]; i++; continue;
        }
        if (i === cells.length - 1 && (c in MB_CLOSE) && /[0-9]$/.test(s)) {
          s += MB_CLOSE[c]; i++; continue;
        }
        if (cells.slice(i, i + 2).join(',') === T.MATH['%'].join(',')) {
          s += '%'; i += 2; continue;
        }
        if (c === T.LETTERSIGN && (cells.slice(i, i + 2).join(',') in MATH2)) {
          s += MATH2[cells.slice(i, i + 2).join(',')]; i += 2; continue;
        }
        // an exercise label: letter sign + letter + full stop.
        // Must come before the Roman numerals: د ل چ م ي خ are Roman letters too.
        if (c === T.LETTERSIGN && cells.length === 3 && i === 0
            && (cells[1] in CELL2LET) && cells[2] === T.PUNCT['.']) {
          s += CELL2LET[cells[1]] + '.'; i += 3; continue;
        }
        if (c === T.LETTERSIGN && cells[i + 1] && (cells[i + 1] in ROM2)) {
          i++;
          while (i < cells.length && (cells[i] in ROM2)) { s += ROM2[cells[i]]; i++; }
          continue;
        }
        if (c === T.NUMSIGN && cells[i + 1] && (cells[i + 1] in LOW2DIG)
            && (i === 0 || ':%({'.includes(s.slice(-1)))) {
          s += '1/'; i++;
          while (i < cells.length && (cells[i] in LOW2DIG)) { s += LOW2DIG[cells[i]]; i++; }
          continue;
        }
        if (c === T.NUMSIGN && (i === 0 || ':%({='.includes(s.slice(-1)))
            && cells[i + 1] && (cells[i + 1] in DIG2)) {
          i++;
          while (i < cells.length && (cells[i] in DIG2)) {
            s += DIG2[cells[i]]; i++;
            if (i < cells.length && cells[i] === T.DECPT && cells[i + 1] && (cells[i + 1] in DIG2)) {
              s += '.'; i++;
            } else if (i < cells.length && cells[i] === T.NUMCOMMA && cells[i + 1] && (cells[i + 1] in DIG2)) {
              s += ','; i++;
            }
          }
          if (i < cells.length && cells[i] === T.RATIO && cells[i + 1] === T.NUMSIGN) {
            s += ':'; i++; continue;
          }
          if (i < cells.length && (cells[i] in LOW2DIG)) {
            s += '/';
            while (i < cells.length && (cells[i] in LOW2DIG)) { s += LOW2DIG[cells[i]]; i++; }
            continue;
          }
          if (i < cells.length && cells[i] === T.NUMEND) i++;
          continue;
        }
        if (c === '236' && s && (s.slice(-1) in ASPIRATE)) {
          s = s.slice(0, -1) + ASPIRATE[s.slice(-1)]; i++; continue;
        }
        if (i === cells.length - 1) {                    // word-final shared cell
          const mark = MARK[c], letter = CELL2LET[c] || '';
          if (!mark)                          s += letter;
          else if (!s)                        s += (letter || mark);
          else if (letter && WORDS.has(s + letter)) s += letter;
          else if (c === '236' && s.length === 1) s += letter;  // ڙھ, لھ — a pair
          else if (WORDS.has(s))              s += mark;
          else if (c === '236')               s += letter;
          else                                s += mark;
          i++; continue;
        }
        if (cells[i] === T.DOUBLING[0] && cells[i + 1] === T.DOUBLING[1]) {
          s = s + ' ' + s; i += 2; continue;              // the word is written twice
        }
        if (c === T.WAW_ATF) { s += ' و '; i++; continue; }
        s += CELL2LET[c] || ''; i++;
      }
      const pc = /^%([0-9][0-9.,]*)$/.exec(s);
      if (pc) s = pc[1] + '%';                 // the guide prints % first (p.51)
      words.push(s);
    }
    // the religious abbreviations read back to the phrase they stand for
    toks.forEach((cs, j) => {
      const key = cs.join(',');
      // the sign wins unless the spelled-out reading is a real word in its own
      // right - the cells of ۽ followed by 236 also read as a word ending in ھ
      const known = WORDS.has(words[j]);
      if (key in SIGN2 && !known) { words[j] = SIGN2[key]; return; }
      if (!known && cs.length > 1 && (cs.slice(0, -1).join(',') in SIGN2)
          && (cs[cs.length - 1] in PUNCT_BACK)) {
        words[j] = SIGN2[cs.slice(0, -1).join(',')] + PUNCT_BACK[cs[cs.length - 1]];
        return;
      }
      if (key in ABB2) {
        if (key === '12356,256') {
          const prev = j ? words[j - 1] : '';
          words[j] = /[0-9]$/.test(prev) ? 'عيسوي' : 'عليه السلام';
        } else words[j] = ABB2[key];
      }
    });
    out.push(words.join(' '));
  }
  return out.join('\n');
}
